#!/usr/bin/env bash
# recipes/crate-gpu-descriptor-types--0-1-2/build.sh -- stage the gpu-descriptor-types 0.1.2 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/gpu-descriptor-types-0.1.2"
